     1→import {ChainConfig} from "@lodestar/config";
     2→import {BLOBSIDECAR_FIXED_SIZE, GENESIS_SLOT} from "@lodestar/params";
     3→import {RespStatus, ResponseError, ResponseOutgoing} from "@lodestar/reqresp";
     4→import {computeEpochAtSlot} from "@lodestar/state-transition";
     5→import {Slot, deneb} from "@lodestar/types";
     6→import {fromHex} from "@lodestar/utils";
     7→import {IBeaconChain} from "../../../chain/index.js";
     8→import {IBeaconDb} from "../../../db/index.js";
     9→import {BLOB_SIDECARS_IN_WRAPPER_INDEX} from "../../../db/repositories/blobSidecars.js";
    10→
    11→export async function* onBlobSidecarsByRange(
    12→  request: deneb.BlobSidecarsByRangeRequest,
    13→  chain: IBeaconChain,
    14→  db: IBeaconDb
    15→): AsyncIterable<ResponseOutgoing> {
    16→  // Non-finalized range of blobs
    17→  const {startSlot, count} = validateBlobSidecarsByRangeRequest(chain.config, request);
    18→  const endSlot = startSlot + count;
    19→
    20→  const finalized = db.blobSidecarsArchive;
    21→  const unfinalized = db.blobSidecars;
    22→  const finalizedSlot = chain.forkChoice.getFinalizedBlock().slot;
    23→
    24→  // Finalized range of blobs
    25→  if (startSlot <= finalizedSlot) {
    26→    // Chain of blobs won't change
    27→    for await (const {key, value: blobSideCarsBytesWrapped} of finalized.binaryEntriesStream({
    28→      gte: startSlot,
    29→      lt: endSlot,
    30→    })) {
    31→      yield* iterateBlobBytesFromWrapper(chain, blobSideCarsBytesWrapped, finalized.decodeKey(key));
    32→    }
    33→  }
    34→
    35→  // Non-finalized range of blobs
    36→  if (endSlot > finalizedSlot) {
    37→    const headRoot = chain.forkChoice.getHeadRoot();
    38→    // TODO DENEB: forkChoice should mantain an array of canonical blocks, and change only on reorg
    39→    const headChain = chain.forkChoice.getAllAncestorBlocks(headRoot);
    40→
    41→    // Iterate head chain with ascending block numbers
    42→    for (let i = headChain.length - 1; i >= 0; i--) {
    43→      const block = headChain[i];
    44→
    45→      // Must include only blobs in the range requested
    46→      if (block.slot >= startSlot && block.slot < endSlot) {
    47→        // Note: Here the forkChoice head may change due to a re-org, so the headChain reflects the canonical chain
    48→        // at the time of the start of the request. Spec is clear the chain of blobs must be consistent, but on
    49→        // re-org there's no need to abort the request
    50→        // Spec: https://github.com/ethereum/consensus-specs/blob/a1e46d1ae47dd9d097725801575b46907c12a1f8/specs/eip4844/p2p-interface.md#blobssidecarsbyrange-v1
    51→
    52→        const blobSideCarsBytesWrapped = await unfinalized.getBinary(fromHex(block.blockRoot));
    53→        if (!blobSideCarsBytesWrapped) {
    54→          // Handle the same to onBeaconBlocksByRange
    55→          throw new ResponseError(RespStatus.SERVER_ERROR, `No item for root ${block.blockRoot} slot ${block.slot}`);
    56→        }
    57→        yield* iterateBlobBytesFromWrapper(chain, blobSideCarsBytesWrapped, block.slot);
